<div class="builder-layout"><section class="builder-components" aria-label="PC components"><?php $groups=$store->buildOptions()['groups'];$labels=['cpu'=>['Processor','The heart of your build.'],'motherboard'=>['Motherboard','Where everything connects.'],'gpu'=>['Graphics card','Bring your world to life.'],'ram'=>['Memory','Space to do more.'],'storage'=>['Storage','Keep your world close.'],'psu'=>['Power supply','Give every component its power.'],'case'=>['Case','A home for your hardware.'],'cooling'=>['CPU cooling','Keep your performance cool.']];foreach($labels as $key=>[$label,$desc]):?><article class="component-row" data-component="<?=$key?>"><div class="component-symbol"><?=ui_icon($key==='psu'?'bolt':($key==='case'?'box':'chip'))?></div><div class="component-info"><p class="eyebrow"><?=ui_e($label)?></p><p class="component-description"><?=ui_e($desc)?></p><label class="sr-only" for="part-<?=$key?>">Choose <?=ui_e($label)?></label><select class="component-select" id="part-<?=$key?>" data-group="<?=$key?>"><option value="">Choose <?=strtolower($label)?></option><?php foreach($groups[$key]??[] as $option):?><option value="<?=(int)$option['variant_id']?>" data-price="<?=(int)$option['price_cents']?>"><?=ui_e($option['name'])?> — <?=ui_money($option['price_cents'])?></option><?php endforeach;?></select><small class="component-picked" hidden></small></div><span class="component-number"><?=array_search($key,array_keys($labels))+1?></span></article><?php endforeach;?></section><aside class="build-summary order-summary"><div class="build-summary-heading"><p class="eyebrow">YOUR BUILD, SO FAR</p><?=ui_icon('chip')?></div><h2>Every part matters.</h2><div class="build-total"><span>Component total</span><strong id="build-total"><?=ui_money(0)?></strong></div><p id="build-budget-status">Choose your first component to get started.</p><div class="build-stats"><div><small>ESTIMATED DRAW</small><strong id="build-watts">— W</strong></div><div><small>SELECTED PARTS</small><strong id="build-count">0 / 8</strong></div></div><div class="compatibility-status"><span class="status-dot"></span><strong id="build-status">Awaiting your selection</strong></div><div id="build-warnings"></div><details class="build-missing"><summary>Information that needs checking</summary><ul id="build-missing"></ul></details><label class="field"><span>Name your build</span><input id="build-name" placeholder="My next PC" maxlength="120"></label><button class="button primary full" id="build-cart">Add build to basket <?=ui_icon('cart')?></button><div class="build-actions"><button class="button secondary" id="build-save"><?=ui_icon('check')?> Save build</button><button class="button secondary" id="build-share"><?=ui_icon('share')?> Share</button></div><button class="button text full" id="build-quote"><?=ui_icon('download')?> Download a quotation</button><div id="build-result" role="status"></div><p class="legal-note">Some parts are clearly labeled demonstration fixtures. Checks use supplied specifications and do not guarantee compatibility. No assembly price is assumed.</p><a class="text-link" href="/support">Ask for professional advice <?=ui_icon('arrow')?></a></aside></div>
